#include <iostream>
using namespace std;

int main() {
    int n, x, a[1005];
    cin >> n >> x;
    for (int i = 0; i < n; i++) cin >> a[i];
    int l = 0, r = n - 1;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (a[mid] == x) {
            cout << mid;
            return 0;
        } else if (a[mid] < x) l = mid + 1;
        else r = mid - 1;
    }
    cout << -1;
    return 0;
}
